import pandas as pd, numpy as np
for name,path in [("exp1",experiment_1_csv),("exp2",experiment_2_csv),("exp4",experiment_4_csv),("exp8",experiment_8_csv),("exp9",experiment_9_csv)]:
    df=pd.read_csv(path)
    print("===",name,df.columns.tolist())
    print(df.mean(numeric_only=True).round(2).to_dict())
    # show unique intervention levels if present
    for c in df.columns:
        if c.startswith("do_"):
            print("  ",c,"unique:",sorted(df[c].dropna().unique())[:6])
    print("  corr clarity:", {k:round(v,3) for k,v in df.corr(numeric_only=True)["WaterClarityScore"].items() if k!="WaterClarityScore"})

